contract InvMutTest {
    C c;
    bool private entered;

    constructor(C _c) { c = _c; }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.Collect(1);
        }
    }

    function run(uint unlockTime, uint initialAmount, uint collectAmount) public payable {
        require(address(this).balance >= initialAmount);

        entered = false;
        c.Put{value: initialAmount}(unlockTime);

        uint sentBefore = address(c).balance;
        (bool s0, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        require(!s0, "outer call must revert");
        require(address(c).balance == sentBefore, "balance must be unchanged after revert");

        (bool g1, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", uint256(0)));
        require(!g1, "inner call must also revert");

        require(entered, "reentrant callback must have been entered");

        uint sentAfter = address(c).balance;
        (bool g2, bytes memory d2) = address(c).call(abi.encodeWithSignature("Collect(uint256)", uint256(0)));

        assert(sentAfter == sentBefore && !g2 && d2.length == 0);
    }
}

contract InvMutTest {
