    function run(uint unlockTime, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(unlockTime <= block.timestamp);

        c.Put{value: depositAmount}(unlockTime);

        uint balBefore = address(c).balance;
        (uint balAcc, uint unlockAcc) = c.Acc(unlockTime) != 0 ? (0, 0) : (0, 0);
        balAcc = 0;
        unlockAcc = 0;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        bool shouldCollect = depositAmount >= c.MinSum() && depositAmount >= collectAmount && block.timestamp > unlockTime;
        assert(reverted != shouldCollect);
        assert(!reverted || balAfter == balBefore);
    }
}

