contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");

        // Set up the caller's account so that it is definitely eligible:
        // put enough Ether (at least MinSum + amount) and unlock immediately.
        uint minSum = c.MinSum();
        uint putAmount = minSum + amount;
        require(address(this).balance >= putAmount, "not enough balance");
        c.Put{value: putAmount}(0);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // The deciding call through Collect.
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // General rule: Collect must not revert when the account is eligible,
        // and on success it must decrease the balance by exactly amount while
        // leaving the unlock time unchanged.
        assert(
            !reverted &&
            afterUnlock == beforeUnlock &&
            beforeBal == putAmount &&
            afterBal + amount == beforeBal
        );
    }

    receive() external payable {}
}

