contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= putAmount, "not enough balance for Put");
        if (putAmount > 0) {
            c.Put{value: putAmount}(unlockTime);
        }

        (uint balBefore, uint unlockBefore) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        (uint balAfter, ) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        if (putAmount == 0) {
            assert(reverted == false);
            assert(balAfter == balBefore);
            assert(cBalAfter == cBalBefore);
            assert(thisBalAfter == thisBalBefore);
        } else {
            assert(reverted == false);
            if (balBefore >= c.MinSum() && balBefore >= collectAmount && block.timestamp > unlockBefore) {
                assert(balAfter == balBefore - collectAmount);
                assert(cBalAfter == cBalBefore - collectAmount);
                assert(thisBalAfter == thisBalBefore + collectAmount);
            } else {
                assert(balAfter == balBefore);
                assert(cBalAfter == cBalBefore);
                assert(thisBalAfter == thisBalBefore);
            }
        }
    }

    receive() external payable {}
}

